def staff_gid(gid: Optional[int] = None) -> int:
    return int(gid if gid is not None else (dashboard_guild() or 0))


CREW_RANKS = {"developer": 40, "owner": 30, "admin": 20, "mod": 10}


def crew_baked(kind: str) -> list:
    return list({"developer": DEVELOPER_IDS, "owner": OWNER_IDS, "admin": ADMIN_IDS, "mod": MOD_IDS}.get(kind, []))


def crew_ids(kind: str, gid: Optional[int] = None) -> list:
    """Env IDs first (locked), then extras saved with /staff add. Legacy owner_id still counts as owner."""
    out = []
    for n in crew_baked(kind) + parse_snowflakes(get_setting(staff_gid(gid), f"crew_{kind}s") or ""):
        if n not in out:
            out.append(n)
    if kind == "owner":
        for n in parse_snowflakes(get_setting(staff_gid(gid), "owner_id") or ""):
            if n not in out:
                out.append(n)
    return out


def owner_id(gid: Optional[int] = None) -> int:
    ids = crew_ids("owner", gid)
    return ids[0] if ids else 0


def crew_rank(uid: int, gid: Optional[int] = None) -> int:
    if not uid:
        return 0
    uid = int(uid)
    for kind, rank in CREW_RANKS.items():
        if uid in crew_ids(kind, gid):
            return rank
    if staff_rec(uid, gid).get("state") == "on":
        return CREW_RANKS["mod"]
    return 0


def crew_at_least(uid: int, kind: str, gid: Optional[int] = None) -> bool:
    return crew_rank(uid, gid) >= CREW_RANKS.get(kind, 99)


def crew_role_name(uid: int, gid: Optional[int] = None) -> str:
    r = crew_rank(uid, gid)
    return {40: "developer", 30: "owner", 20: "admin", 10: "mod"}.get(r, "")


def crew_locked(kind: str, uid: int) -> bool:
    return int(uid) in crew_baked(kind) or (kind != "developer" and int(uid) in crew_baked("developer"))


def crew_save_extras(kind: str, ids: list, gid: Optional[int] = None) -> None:
    baked = set(crew_baked(kind))
    extra = [i for i in ids if i not in baked]
    set_setting(staff_gid(gid), f"crew_{kind}s", ",".join(str(i) for i in extra) or None)


def crew_grant(kind: str, uid: int, name: Optional[str] = None, gid: Optional[int] = None) -> str:
    """Put this Discord user on owner / admin / mod. Developers stay env-only."""
    uid = int(uid)
    if kind not in ("owner", "admin", "mod"):
        return "role"
    if uid in crew_ids("developer", gid):
        return "dev"
    if kind != "owner" and uid not in OWNER_IDS and owner_id(gid) == uid:
        set_setting(staff_gid(gid), "owner_id", None)
    for other in ("owner", "admin", "mod"):
        leftover = [i for i in parse_snowflakes(get_setting(staff_gid(gid), f"crew_{other}s") or "") if i != uid]
        if other == kind and uid not in crew_baked(kind):
            leftover.append(uid)
        crew_save_extras(other, leftover, gid)
    staff_put(uid, "on", name, gid)
    return "ok"


def crew_revoke(uid: int, gid: Optional[int] = None) -> str:
    uid = int(uid)
    if uid in crew_ids("developer", gid):
        return "dev"
    if uid in OWNER_IDS:
        return "env"
    for kind in ("owner", "admin", "mod"):
        leftover = [i for i in parse_snowflakes(get_setting(staff_gid(gid), f"crew_{kind}s") or "") if i != uid]
        crew_save_extras(kind, leftover, gid)
    if owner_id(gid) == uid and uid not in OWNER_IDS:
        set_setting(staff_gid(gid), "owner_id", None)
    staff_put(uid, None, gid=gid)
    return "ok"


def owner_claim(uid: int, gid: Optional[int] = None) -> bool:
    """True when this person is (or just became) an owner. Developers may always claim a vacant owner slot."""
    if uid in crew_ids("owner", gid):
        return True
    if crew_ids("owner", gid) and not crew_at_least(uid, "developer", gid):
        return False
    crew_grant("owner", uid, gid=gid)
    return True


def crew_display_name(uid: int, gid: Optional[int] = None) -> str:
    rec = staff_rec(uid, gid)
    nm = rec.get("name") or ""
    if nm and not str(nm).isdigit():
        return clip(nm, 40)
    try:
        g = bot.get_guild(int(gid or staff_gid() or 0))
        m = g.get_member(int(uid)) if g else None
        n = (getattr(m, "display_name", None) or getattr(m, "name", None)) if m is not None else None
        if not n:
            u = bot.get_user(int(uid)) if hasattr(bot, "get_user") else None
            n = getattr(u, "display_name", None) or getattr(u, "name", None) if u is not None else None
        if n and not str(n).isdigit():
            if rec.get("state"):
                staff_put(uid, rec.get("state"), n, gid)
            return clip(n, 40)
    except Exception:
        pass
    try:
        row = db().execute(
            "SELECT bettor_name FROM picks WHERE bettor_id = ? AND bettor_name IS NOT NULL AND bettor_name != '' "
            "LIMIT 1", (int(uid),)).fetchone()
        if row and row["bettor_name"] and not str(row["bettor_name"]).isdigit():
            return clip(row["bettor_name"], 40)
    except Exception:
        pass
    return str(uid)


def note_slip_read(how: str, pick_id=None, who: str = "", title: str = "", url: str = "") -> None:
    try:
        items = json.loads(get_setting(0, "slipread_log") or "[]")
    except Exception:
        items = []
    if not isinstance(items, list):
        items = []
    items.insert(0, {"how": clip(how, 16), "id": pick_id, "who": clip(who, 40),
                     "title": clip(title, 80), "url": clip(url, 160), "at": now_iso()})
    set_setting(0, "slipread_log", json.dumps(items[:50]))


def crash_note(kind: str, title: str, why: str, gid: Optional[int] = None) -> None:
    g = staff_gid(gid)
    text = clip(f"{title}: {why}", 180)
    staff_log_add(g, kind, text, "robot")
    try:
        items = json.loads(get_setting(g, "crash_log") or "[]")
    except Exception:
        items = []
    if not isinstance(items, list):
        items = []
    items.insert(0, {"kind": clip(kind, 12), "title": clip(title, 60), "why": clip(why, 140), "at": now_iso()})
    set_setting(g, "crash_log", json.dumps(items[:24]))


async def crash_notify(client, kind: str, title: str, why: str) -> None:
    crash_note(kind, title, why)
    if kind in ("ok", "info"):
        return
    card = None
    try:
        card = status_card({
            "title": "HEADS UP",
            "tone": "crash",
            "happened": title,
            "news": [clip(why, 180)],
            "news_label": "DETAILS",
        })
    except Exception:
        log.warning("Crash card failed", exc_info=True)
    await post_alert(client, f"🚨 **{title}**\n{clip(why, 300)}", ping=True, file=card)


def alert_channel_ids(guild_id: int) -> list[int]:
    """Recap first (the group chat), then audit, then tickets."""
    ids = []
    for key in ("recap_channel", "audit_channel", "ticket_channel"):
        v = get_setting(guild_id, key)
        if v and str(v).isdigit():
            n = int(v)
            if n not in ids:
                ids.append(n)
    return ids


def bot_gap_seconds(since: Optional[str]) -> Optional[int]:
    if not since:
        return None
    try:
        t = datetime.fromisoformat(str(since).replace("Z", "+00:00"))
        if t.tzinfo is None:
            t = t.replace(tzinfo=timezone.utc)
        return max(0, int((datetime.now(timezone.utc) - t.astimezone(timezone.utc)).total_seconds()))
    except Exception:
        return None


def bot_gap_words(sec: int) -> str:
    if sec < 90:
        return f"{sec}s"
    if sec < 3600:
        return f"{sec // 60} min"
    h, m = divmod(sec // 60, 60)
    return f"{h}h {m}m" if m else f"{h}h"


def bot_update_lines(prev: str) -> list[str]:
    """Notes for versions after `prev`. Unknown/empty prev → the full current list (first announce)."""
    if not prev:
        return [line for _, line in BOT_UPDATES]
    started = False
    out = []
    for ver, line in BOT_UPDATES:
        if started:
            out.append(line)
        if ver in str(prev):
            started = True
    if not out:
        return [line for ver, line in BOT_UPDATES if ver in BOT_VERSION]
    return out


def boot_notice(prev_ver: str, gap_sec: Optional[int], planned: bool) -> Optional[str]:
    """The recap-channel note for a new upload and/or a real outage. None when nothing to say."""
    new = (prev_ver or "") != BOT_VERSION
    down = gap_sec is not None and gap_sec >= 180
    if not new and not down:
        return None
    bits = [f"🛠️ **PIMP-BOT is live · {BOT_VERSION}**"]
    if down:
        bits.append("**What happened**")
        bits.append("Back from an update." if planned else f"Was down about {bot_gap_words(gap_sec)}.")
    elif new:
        bits.append("New upload. It was not down long enough to call it an outage.")
    if new:
        notes = bot_update_lines(prev_ver)
        show = notes[-3:]
        if show:
            bits.append("**What's new**")
            bits.extend(f"• {n}" for n in show)
            extra = len(notes) - len(show)
            if extra:
                bits.append(f"• {extra} older notes are on the site, under More.")
    return "\n".join(bits)


async def _alert_channel(client, cid: int):
    ch = client.get_channel(cid) if cid else None
    if ch is not None:
        return ch
    fetch = getattr(client, "fetch_channel", None)
    if fetch is None:
        return None
    try:
        return await fetch(cid)
    except Exception:
        return None


async def post_alert(client, text: str, *, ping: bool = False, file: Optional[io.BytesIO] = None) -> int:
    """One message per server, recap channel first. Returns how many channels took it."""
    sent = 0
    guilds = list(getattr(client, "guilds", None) or [])
    gids = [g.id for g in guilds if getattr(g, "id", None)]
    if not gids:
        gids = [r["guild_id"] for r in db().execute(
            "SELECT DISTINCT guild_id FROM settings WHERE key IN ('recap_channel','audit_channel','ticket_channel')")]
    body = text
    mentions = discord.AllowedMentions.none()
    if ping and OWNER_IDS:
        body = text + "\n" + " ".join(f"<@{i}>" for i in OWNER_IDS[:4])
        mentions = discord.AllowedMentions(everyone=False, roles=False, users=True)
    seen = set()

    def _file():
        if file is None:
            return None
        try:
            file.seek(0)
            return discord.File(file, filename="status.png")
        except Exception:
            return None

    async def _send(ch):
        attachment = _file()
        if attachment is not None:
            try:
                await ch.send(body, allowed_mentions=mentions, file=attachment)
                return
            except TypeError:
                pass
        await ch.send(body, allowed_mentions=mentions)

    for gid in gids:
        if gid in seen:
            continue
        seen.add(gid)
        posted = False
        for cid in alert_channel_ids(gid):
            ch = await _alert_channel(client, cid)
            if ch is None:
                continue
            try:
                await _send(ch)
                posted, sent = True, sent + 1
                break
            except Exception:
                log.warning("Alert failed in channel %s guild %s", cid, gid)
        if posted:
            continue
        g = next((x for x in guilds if getattr(x, "id", None) == gid), None)
        sysch = getattr(g, "system_channel", None) if g is not None else None
        if sysch is None:
            continue
        try:
            await _send(sysch)
            sent += 1
        except Exception:
            log.warning("Alert failed in system channel guild %s", gid)
    return sent


def boot_facts() -> list[tuple[str, str]]:
    """(label, value) pairs for the restart picture. Only facts the bot can measure."""
    free, total, db_n = disk_bytes()
    free_mb = free // (1024 * 1024)
    db_mb = db_n / (1024 * 1024)
    if not total:
        disk = "could not be measured"
    elif free < 50 * 1024 * 1024:
        disk = f"almost full, {free_mb} MB free"
    elif free < 200 * 1024 * 1024:
        disk = f"low, {free_mb} MB free"
    else:
        disk = f"fine, {free_mb} MB free"
    rows = [("Disk", f"{disk}. Picks file {db_mb:.1f} MB.")]
    try:
        opens = db().execute("SELECT COUNT(*) AS n FROM picks WHERE status = 'open'").fetchone()["n"]
        start = datetime.now(TZ).replace(hour=0, minute=0, second=0, microsecond=0).astimezone(timezone.utc)
        logged = db().execute("SELECT COUNT(*) AS n FROM picks WHERE created_at >= ?",
                              (start.isoformat(timespec="seconds"),)).fetchone()["n"]
        rows.append(("Open slips", f"{opens}. Logged today: {logged}."))
    except Exception:
        pass
    try:
        rows.append(("Scanner", "on." if TESSERACT else "off on this host."))
    except Exception:
        pass
    try:
        names = []
        if xai_ready():
            names.append("Grok")
        if GROQ_API_KEY:
            names.append("Groq")
        if GEMINI_API_KEY:
            names.append("Gemini")
        if ai_enabled() and claude_alive():
            names.append("Claude")
        elif ai_enabled():
            names.append("Claude paused")
        rows.append(("Answers", (", ".join(names) if names else "none set") + "."))
    except Exception:
        pass
    try:
        err = SLIP_STATE.get("last_error")
    except Exception:
        err = None
    if err and len(err) > 1 and err[1]:
        rows.append(("Last scan problem", clip(str(err[1]), 120)))
    return rows


def boot_health_lines() -> list[str]:
    """A short status block for the recap note. Only facts the bot can measure."""
    return ["**Right now**"] + [f"• {k}: {v}" for k, v in boot_facts()]


def status_card(data: dict) -> Optional[io.BytesIO]:
    """Tonight's Board style picture for a restart or a crash. None if drawing fails."""
    try:
        payload = dict(data)
        payload.setdefault("when", datetime.now(TZ).strftime("%a %b %-d · %-I:%M %p"))
        payload.setdefault("rows", boot_facts())
        return render_status_card(payload)
    except Exception:
        log.warning("Status card failed", exc_info=True)
        return None


async def storage_alert(client) -> None:
    """Once a night: tell mods and admins when the disk or the scanner needs a person."""
    free, total, db_n = disk_bytes()
    today = datetime.now(TZ).date().isoformat()
    try:
        counts = json.loads(get_setting(0, f"slipreads:{today}") or "{}")
    except ValueError:
        counts = {}
    fails = int(counts.get("fail") or 0)
    if free and free < 200 * 1024 * 1024:
        await crash_notify(client, "bot", "Storage is low",
                           f"{free // (1024 * 1024)} MB free of {total // (1024 * 1024)} MB. "
                           f"Database is {db_n // (1024 * 1024)} MB. Old backup copies were removed.")
    if fails >= 8:
        await crash_notify(client, "bot", "Scanner missed a lot today",
                           f"{fails} screenshots could not be read today. A clearer crop, or a Gemini key, covers the rest.")


async def announce_boot(client) -> Optional[str]:
    """On process start: tell the recap channel if the version changed or we were gone."""
    try:
        sweep_storage()
    except Exception:
        log.warning("Storage sweep failed", exc_info=True)
    prev = get_setting(0, "bot_announced") or ""
    hb = get_setting(0, "bot_heartbeat")
    planned = bool(get_setting(0, "bot_stopping"))
    gap = bot_gap_seconds(get_setting(0, "bot_disconnect_at") or hb)
    note = boot_notice(prev, gap, planned)
    set_setting(0, "bot_heartbeat", now_iso())
    set_setting(0, "bot_announced", BOT_VERSION)
    set_setting(0, "bot_stopping", None)
    set_setting(0, "bot_disconnect_at", None)
    if not note:
        free, _, _ = disk_bytes()
        if not free or free >= 200 * 1024 * 1024:
            return None
        note = (f"🛠️ **PIMP-BOT is live · {BOT_VERSION} · update {ROADMAP_NOW}**\n"
                "Storage is low, so this restart is being reported.")
    health = boot_health_lines()
    if health:
        note = note + "\n" + "\n".join(health)
    if not note:
        return None
    crash_note("ok" if planned or prev == BOT_VERSION else "bot", "PIMP-BOT is live",
               clip(note.replace("\n", " · "), 180))
    happened = ""
    if gap and gap >= 180:
        happened = "Back from an update." if planned else f"Was down about {bot_gap_words(gap)}."
    elif (prev or "") != BOT_VERSION:
        happened = "New upload. It was not down long enough to call it an outage."
    elif "Storage is low" in (note or ""):
        happened = "Storage is low, so this restart is being reported."
    news = bot_update_lines(prev)[-3:] if (prev or "") != BOT_VERSION else []
    tone = "down" if gap and gap >= 180 and not planned else "live"
    try:
        await post_alert(client, note, ping=bool(gap and gap >= 180 and not planned), file=status_card({
            "title": "PIMP-BOT IS LIVE", "tone": tone, "happened": happened, "news": news}))
    except Exception:
        log.warning("Boot announce failed")
    return note


def staff_rec(uid: int, gid: Optional[int] = None) -> dict:
    raw = get_setting(staff_gid(gid), f"staff:{uid}") or ""
    if raw.startswith("{"):
        try:
            d = json.loads(raw)
            if isinstance(d, dict):
                return d
        except Exception:
            pass
    return {"state": raw} if raw else {}


def staff_put(uid: int, state: Optional[str], name: Optional[str] = None, gid: Optional[int] = None) -> None:
    prev = staff_rec(uid, gid)
    g = staff_gid(gid)
    if state is None:
        set_setting(g, f"staff:{uid}", None)
        return
    set_setting(g, f"staff:{uid}", json.dumps({
        "state": state, "name": clip(name or prev.get("name") or str(uid), 40)}))


def staff_rows(state: Optional[str] = None, gid: Optional[int] = None) -> list:
    out = []
    for r in db().execute("SELECT key, value FROM settings WHERE guild_id = ? AND key LIKE 'staff:%'",
                          (staff_gid(gid),)):
        uid_s = str(r["key"]).split(":", 1)[-1]
        if not uid_s.isdigit():
            continue
        try:
            d = json.loads(r["value"]) if (r["value"] or "").startswith("{") else {"state": r["value"]}
        except Exception:
            d = {"state": r["value"]}
        if state and d.get("state") != state:
            continue
        out.append({"id": int(uid_s), "name": clip(d.get("name") or uid_s, 40), "state": d.get("state") or ""})
    return out


def staff_web_ok(uid: int, gid: Optional[int] = None) -> bool:
    return crew_at_least(uid, "mod", gid)


def staff_pass(uid: int) -> str:
    sig = hmac.new(dashboard_key().encode(), f"staff:{uid}".encode(), hashlib.sha256).hexdigest()[:24]
    return f"{uid}.{sig}"


def staff_pass_ok(token: Optional[str]) -> Optional[int]:
    if not token or token.count(".") != 1:
        return None
    uid_s, sig = token.split(".", 1)
    if not uid_s.isdigit() or len(sig) != 24:
        return None
    uid = int(uid_s)
    want = staff_pass(uid)
    if len(want) != len(token) or not hmac.compare_digest(want.encode(), token.encode()):
        return None
    return uid if staff_web_ok(uid) else None


def staff_site_url(uid: int) -> Optional[str]:
    if not PUBLIC_DOMAIN or not staff_web_ok(uid):
        return None
    return f"https://{PUBLIC_DOMAIN}/staff?pass={staff_pass(uid)}"


def staff_uid_from_request(request) -> Optional[int]:
    tok = (getattr(request, "cookies", None) or {}).get(DASH_STAFF_COOKIE) or ""
    return staff_pass_ok(tok)


def site_look(gid: Optional[int] = None) -> tuple:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "sitelook") or "{}")
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        raw = {}
    bg = raw.get("bg") if raw.get("bg") in SITE_BGS else "court"
    accent = raw.get("accent") if raw.get("accent") in BRAND_PRESETS else "purple"
    return bg, accent, BRAND_PRESETS[accent]


def site_look_save(bg: Optional[str] = None, accent: Optional[str] = None, gid: Optional[int] = None) -> tuple:
    cur_bg, cur_ac, _ = site_look(gid)
    if bg in SITE_BGS:
        cur_bg = bg
    if accent in BRAND_PRESETS:
        cur_ac = accent
    set_setting(staff_gid(gid), "sitelook", json.dumps({"bg": cur_bg, "accent": cur_ac}))
    return site_look(gid)


def dash_paint_look(html: str) -> str:
    """Default look stays byte-identical to the shipped HTML (tests compare the full page)."""
    bg, accent, rgb = site_look()
    if bg == "court" and accent == "purple":
        return html
    hx = _brand_hex(rgb)
    css = (f"<style id=look>:root{{--brand:{hx};--brand2:{hx}cc;--gold:#f0b429}}"
           f"body{{background:{SITE_BGS[bg][1]}!important}}</style>")
    html = html.replace("</head>", css + "</head>", 1)
    if 'class="v4"' in html:
        html = html.replace('<body class="v4">', f'<body class="v4" data-bg="{bg}" data-accent="{accent}">', 1)
        html = html.replace('<body class="v4 has-staff">',
                            f'<body class="v4 has-staff" data-bg="{bg}" data-accent="{accent}">', 1)
    else:
        html = html.replace("<body>", f'<body data-bg="{bg}" data-accent="{accent}">', 1)
    return html


def dash_staff_inject(html: str, request) -> str:
    if "body.v4" not in html and 'class="v4"' not in html:
        return html
    if not staff_uid_from_request(request):
        return html
    if 'class="staffbtn"' in html:
        return html
    html = html.replace('<body class="v4">', '<body class="v4 has-staff">', 1)
    html = html.replace('<button class="iconbtn" id="theme"',
                        '<a class="staffbtn" href="/staff">Staff HQ</a><button class="iconbtn" id="theme"', 1)
    return html


def staff_log_add(gid: Optional[int], kind: str, text: str, name: str = "") -> None:
    g = staff_gid(gid)
    try:
        items = json.loads(get_setting(g, "staff_log") or "[]")
    except Exception:
        items = []
    if not isinstance(items, list):
        items = []
    items.insert(0, {"kind": clip(kind, 12), "text": clip(text, 140), "name": clip(name, 40), "at": now_iso()})
    set_setting(g, "staff_log", json.dumps(items[:40]))


ASK_QUOTA_DEFAULT = [
    {"id": "new", "name": "New activity 0+", "n": 5},
    {"id": "regular", "name": "Regular activity 5+", "n": 10},
    {"id": "active", "name": "Active activity 15+", "n": 20},
    {"id": "core", "name": "Core activity 40+", "n": 35},
    {"id": "staff", "name": "Mods and owners", "n": 0},
]


def staff_quota_rows(gid: Optional[int] = None) -> list:
    try:
        raw = json.loads(get_setting(staff_gid(gid), "ask_quota") or "[]")
    except Exception:
        raw = []
    by_id = {x.get("id"): x for x in raw if isinstance(x, dict) and x.get("id")}
    out = []
    for row in ASK_QUOTA_DEFAULT:
        cur = by_id.get(row["id"], row)
        n = cur.get("n", row["n"])
        try:
            n = int(n)
        except (TypeError, ValueError):
            n = row["n"]
        out.append({"id": row["id"], "name": row["name"], "n": n,
                    "label": "unlimited" if int(n) == 0 else f"{int(n)} a day"})
    return out


def staff_channel_name(gid: int, cid) -> str:
    try:
        g = bot.get_guild(int(gid))
        ch = g.get_channel(int(cid)) if g else None
        if ch is not None:
            return getattr(ch, "name", None) or str(cid)
    except Exception:
        pass
    return str(cid or "")


def staff_channels(gid: int) -> list:
    out = []
    try:
        g = bot.get_guild(int(gid))
        for ch in list(getattr(g, "text_channels", None) or [])[:40]:
            out.append({"id": ch.id, "name": getattr(ch, "name", str(ch.id))})
    except Exception:
        pass
    if not out:
        for key, label in (("ticket_channel", "staff-tickets"), ("audit_channel", "audit"),
                           ("recap_channel", "recap")):
            cid = get_setting(gid, key)
            if cid:
                out.append({"id": int("".join(c for c in str(cid) if c.isdigit()) or 0), "name": label})
    return [c for c in out if c["id"]]


def acct_clean_name(name: str) -> Optional[str]:
    s = re.sub(r"[^A-Za-z0-9_]+", "_", (name or "").strip())[:24].strip("_")
    return s if len(s) >= 3 else None


def acct_fresh_name(name: str) -> str:
    base = acct_clean_name(name) or "user"
    cand, n = base, 2
    while db().execute("SELECT 1 FROM accounts WHERE name = ?", (cand,)).fetchone():
        cand = clip(f"{base}{n}", 24)
        n += 1
    return cand


def acct_hash(password: str) -> str:
    return hashlib.pbkdf2_hmac("sha256", password.encode(), dashboard_key().encode(), 120000).hex()


def acct_cookie(aid: int) -> str:
    sig = hmac.new(dashboard_key().encode(), f"acct:{aid}".encode(), hashlib.sha256).hexdigest()[:24]
    return f"{aid}.{sig}"


def acct_cookie_ok(token: Optional[str]) -> Optional[int]:
    if not token or token.count(".") != 1:
        return None
    aid_s, sig = token.split(".", 1)
    if not aid_s.isdigit() or len(sig) != 24:
        return None
    want = acct_cookie(int(aid_s))
    if len(want) != len(token) or not hmac.compare_digest(want.encode(), token.encode()):
        return None
    return int(aid_s)


def acct_from_request(request) -> Optional[dict]:
    aid = acct_cookie_ok((getattr(request, "cookies", None) or {}).get(DASH_ACCT_COOKIE) or "")
    if not aid:
        return None
    row = db().execute("SELECT * FROM accounts WHERE id = ?", (aid,)).fetchone()
    return dict(row) if row else None


def acct_touch(aid: int, how: str) -> None:
    db().execute("UPDATE accounts SET last_seen = ? WHERE id = ?", (now_iso(), aid))
    db().execute("INSERT INTO account_access (account_id, at, how) VALUES (?,?,?)", (aid, now_iso(), clip(how, 40)))
    db().commit()


def acct_login_token(aid: int) -> str:
    exp = str(int(time.time()) + 600)
    sig = hmac.new(dashboard_key().encode(), f"dlogin:{aid}:{exp}".encode(), hashlib.sha256).hexdigest()[:20]
    return f"{aid}.{exp}.{sig}"


def acct_login_ok(token: Optional[str]) -> Optional[int]:
    if not token or token.count(".") != 2:
        return None
    aid_s, exp, sig = token.split(".")
    if not aid_s.isdigit() or not exp.isdigit() or int(exp) < time.time():
        return None
    want = hmac.new(dashboard_key().encode(), f"dlogin:{aid_s}:{exp}".encode(), hashlib.sha256).hexdigest()[:20]
    if len(want) != len(sig) or not hmac.compare_digest(want.encode(), sig.encode()):
        return None
    return int(aid_s)


def staff_ticket_add(guild_id: int, message) -> None:
    text = clip(getattr(message, "content", "") or "(attachment)", 200)
    if not text.strip():
        return
    db().execute(
        "INSERT INTO staff_tickets (guild_id, channel_id, message_id, author_id, author_name, text, status, created_at) "
        "VALUES (?,?,?,?,?,?,?,?)",
        (guild_id, getattr(message.channel, "id", None), getattr(message, "id", None),
         getattr(message.author, "id", None), clip(getattr(message.author, "display_name", None) or "Member", 40),
         text, "open", now_iso()))
    db().commit()


def staff_ops(uid: int) -> dict:
    """Numbers and lists for Staff HQ. Names only; nothing a person typed is marked HTML."""
    gid = staff_gid()
    clean = unsure = failed = 0
    asks = {"ask_groq": 0, "ask_gemini": 0, "ask_claude": 0}
    for i in range(7):
        day = (datetime.now(TZ).date() - timedelta(days=i)).isoformat()
        try:
            c = json.loads(get_setting(0, f"slipreads:{day}") or "{}")
        except Exception:
            c = {}
        if not isinstance(c, dict):
            c = {}
        num = lambda k, d=c: int(d[k]) if str(d.get(k) or "").isdigit() else 0
        clean += num("scan")
        unsure += num("scan_confirm")
        failed += num("fail")
        if i == 0:
            for k in asks:
                asks[k] = num(k)
    tickets = []
    try:
        for t in db().execute(
                "SELECT id, author_name, text, status FROM staff_tickets WHERE guild_id = ? AND status = 'open' "
                "ORDER BY id DESC LIMIT 20", (gid,)):
            tickets.append({"id": "d" + str(t["id"]), "who": clip(t["author_name"], 40),
                            "title": clip(t["text"], 90), "state": "open", "kind": "discord"})
    except Exception:
        pass
    for need in dash_needs(gid)[:12]:
        tickets.append({"id": need.get("id"), "who": need["who"], "title": need["why"], "state": "open",
                        "kind": "grade" if "grade" in (need.get("why") or "").lower() else "pay"})
    try:
        cutoff = iso(datetime.now(timezone.utc) - timedelta(days=4))
        for p in db().execute(
                "SELECT id, bettor_name FROM picks WHERE guild_id = ? AND status = 'open' AND created_at <= ? "
                "AND (hidden IS NULL OR hidden = 0) ORDER BY id LIMIT 8", (gid, cutoff)):
            if not any(t.get("id") == p["id"] for t in tickets):
                tickets.append({"id": p["id"], "who": clip(p["bettor_name"], 40),
                                "title": f"Slip #{p['id']} has been open 4+ days", "state": "open", "kind": "stale"})
    except Exception:
        pass
    closed = 0
    try:
        week = iso(datetime.now(timezone.utc) - timedelta(days=7))
        closed = db().execute(
            "SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND status != 'open' AND settled_at >= ?",
            (gid, week)).fetchone()["n"]
        closed += db().execute(
            "SELECT COUNT(*) AS n FROM staff_tickets WHERE guild_id = ? AND status != 'open' "
            "AND COALESCE(closed_at, created_at) >= ?", (gid, week)).fetchone()["n"]
    except Exception:
        pass
    raw_ch = get_setting(gid, "ticket_channel") or ""
    ch_digits = "".join(c for c in str(raw_ch) if c.isdigit())
    ch_label = staff_channel_name(gid, ch_digits) if ch_digits else "staff-tickets"
    if str(ch_label).isdigit():
        ch_label = "staff-tickets"
    try:
        blacklist = json.loads(get_setting(gid, "staff_blacklist") or "[]")
    except Exception:
        blacklist = []
    if not isinstance(blacklist, list):
        blacklist = []
    hits = []
    try:
        for p in db().execute(
                f"SELECT bettor_name, description, settled_at FROM picks WHERE guild_id = ? AND status != 'open' "
                f"AND {_DASH_VISIBLE} ORDER BY settled_at DESC LIMIT 5", (gid,)):
            hits.append({"who": clip(p["bettor_name"], 40), "what": clip(shown_desc(p), 80),
                         "when": local_day(p["settled_at"]) if p["settled_at"] else ""})
    except Exception:
        pass
    try:
        log_rows = json.loads(get_setting(gid, "staff_log") or "[]")
    except Exception:
        log_rows = []
    if not isinstance(log_rows, list):
        log_rows = []
    anns = []
    try:
        for a in db().execute(
                "SELECT text, due_at, sent_at, channel_id FROM announcements WHERE guild_id = ? "
                "ORDER BY COALESCE(sent_at, due_at) DESC LIMIT 6", (gid,)):
            anns.append({"text": clip(a["text"], 120), "due": a["due_at"] or "",
                         "sent": bool(a["sent_at"]),
                         "channel": staff_channel_name(gid, a["channel_id"]) if a["channel_id"] else ""})
    except Exception:
        pass
    crew = []
    for kind in ("developer", "owner", "admin", "mod"):
        for i in crew_ids(kind, gid):
            rec = staff_rec(i, gid)
            crew.append({"id": i, "name": crew_display_name(i, gid), "role": kind})
    pending = staff_rows("pending", gid) if crew_at_least(uid, "owner", gid) else []
    pool = [
        {"name": "Grok (xAI)", "on": xai_ready()},
        {"name": "Groq (free)", "on": bool(env("GROQ_API_KEY", ""))},
        {"name": "Cerebras (free)", "on": bool(env("CEREBRAS_API_KEY", ""))},
        {"name": "OpenRouter (free)", "on": bool(env("OPENROUTER_API_KEY", ""))},
        {"name": "Gemini (free)", "on": bool(env("GEMINI_API_KEY", ""))},
        {"name": "Claude (paid)", "on": bool(ANTHROPIC_API_KEY)},
    ]
    quota = staff_quota_rows(gid)
    servers = []
    try:
        health = dash30_health()
        for f in (health.get("feeds") or [])[:18]:
            st = f.get("state") or "idle"
            detail = []
            if f.get("last_ok"):
                detail.append("last ok " + str(f["last_ok"]))
            elif f.get("ago"):
                detail.append("last ok " + str(f["ago"]))
            if f.get("ok") or f.get("fail"):
                detail.append(f"{int(f.get('ok') or 0)} ok · {int(f.get('fail') or 0)} fail")
            if f.get("code"):
                detail.append("http " + str(f["code"]))
            if st == "idle":
                detail.append("waiting for a call")
            elif st == "down":
                detail.append("offline")
            elif st in ("shaky", "warn"):
                detail.append("caution")
            servers.append({"name": f.get("name") or "feed", "state": st, "kind": "feed",
                            "detail": " · ".join(detail), "ago": f.get("last_ok") or f.get("ago") or ""})
        cyc = health.get("cycle") or {}
        jobs = health.get("jobs") or {}
        servers.append({"name": "Robot loop", "state": "ok" if cyc.get("ok") else "down", "kind": "bot",
                        "detail": ("ran " + str(cyc.get("ago") or "never")) + (
                            f" · {len(jobs.get('failing') or [])} job(s) failing" if jobs.get("failing") else "")})
    except Exception:
        pass
    try:
        for g in list(getattr(bot, "guilds", None) or [])[:12]:
            n = getattr(g, "member_count", None) or len(getattr(g, "members", []) or [])
            chans = len(getattr(g, "text_channels", []) or [])
            servers.append({"name": clip(getattr(g, "name", None) or str(getattr(g, "id", "")), 40),
                            "state": "ok", "kind": "discord",
                            "detail": f"{n} members · {chans} text channels · id {g.id}", "ago": ""})
    except Exception:
        pass
    try:
        slog = json.loads(get_setting(0, "slipread_log") or "[]")
    except Exception:
        slog = []
    if not isinstance(slog, list):
        slog = []
    try:
        crashes = json.loads(get_setting(gid, "crash_log") or "[]")
    except Exception:
        crashes = []
    if not isinstance(crashes, list):
        crashes = []
    return {
        "me": {"id": uid, "role": crew_role_name(uid, gid) or "staff", "boss": crew_at_least(uid, "owner", gid)},
        "reads": {"clean": clean, "unsure": unsure, "failed": failed, "slips": [x for x in slog if isinstance(x, dict)][:18]},
        "pool": pool, "quota": quota, "asks": asks, "servers": servers, "channels": staff_channels(gid),
        "tickets": {"channel": ch_label, "closed": int(closed or 0), "open": tickets[:12]},
        "blacklist": [x for x in blacklist if isinstance(x, dict)][:20],
        "hits": hits, "log": log_rows[:12], "announce": anns, "crew": crew, "pending": pending,
        "crashes": [x for x in crashes if isinstance(x, dict)][:12], "version": BOT_VERSION,
        "update": ROADMAP_NOW,
        "access": {"key": dash_gate_code(), "day": dash_gate_state().get("day") or "",
                   "used": int(dash_gate_state().get("used") or 0)},
        "devices": [{"id": r.get("id") or "", "who": r.get("who") or "Browser", "ip": r.get("ip") or "",
                     "when": r.get("when") or ""} for r in dash_devices()],
    }


