EXPORT_FORMATS = [
    app_commands.Choice(name="Excel (Kalshi, PrizePicks and Summary tabs)", value="xlsx"),
    app_commands.Choice(name="CSV (one plain list)", value="csv"),
]


@bot.tree.command(name="export", description="Download every pick as a spreadsheet")
@app_commands.guild_only()
@app_commands.describe(format="Excel by default")
@app_commands.choices(format=EXPORT_FORMATS)
@sec_rate("file")
async def export_cmd(interaction: discord.Interaction,
                     format: Optional[app_commands.Choice[str]] = None):
    rows = db().execute(
        "SELECT * FROM picks WHERE guild_id = ? ORDER BY id", (interaction.guild_id,)
    ).fetchall()
    if not rows:
        await interaction.response.send_message("No picks to export yet.", ephemeral=True)
        return
    stamp = datetime.now(TZ).strftime("%Y-%m-%d")
    if format is None or format.value == "xlsx":
        data = build_workbook(interaction.guild_id)
        people = len({r["bettor_key"] for r in rows})
        await interaction.response.send_message(
            f"{len(rows)} picks from {people} {'person' if people == 1 else 'people'}.",
            file=discord.File(data, filename=f"picks_{stamp}.xlsx"))
        return
    buf = io.StringIO()
    writer = QaCsvWriter(buf)
    writer.writerow(["Pick #", "Logged (UTC)", "Bettor", "Platform", "Sport", "Description",
                     "Legs", "Legs Hit", "Cost", "Max Payout", "Status", "Returned", "Net",
                     "Settled (UTC)", "Slip", "Notes"])
    for p in rows:
        settled = p["status"] != "open"
        legs = [] if sec_secret(p) else get_legs(p["id"])
        legs_text = " | ".join(f"{leg['text']} [{leg['status']}]" for leg in legs)
        legs_hit = f"{sum(1 for leg in legs if leg['status'] == 'hit')}/{len(legs)}" if legs else ""
        writer.writerow([
            p["id"], p["created_at"], p["bettor_name"], p["platform"], p["sport"] or "",
            shown_desc(p), legs_text, legs_hit,
            f"{p['cost']:.2f}", f"{p['payout']:.2f}", p["status"],
            f"{p['returned']:.2f}" if settled else "",
            f"{(p['returned'] or 0.0) - p['cost']:.2f}" if settled else "",
            p["settled_at"] or "", p["slip_url"] or "", "" if sec_secret(p) else (p["notes"] or ""),
        ])
    data = io.BytesIO(buf.getvalue().encode("utf-8-sig"))  # BOM so Excel reads it right
    await interaction.response.send_message(
        f"{len(rows)} picks.", file=discord.File(data, filename=f"picks_{stamp}.csv"))


# ---- channel setup ----------------------------------------------------------

@bot.tree.command(name="receipts",
                  description="Auto-log slip screenshots: this channel, every channel, or off")
@app_commands.guild_only()
@app_commands.default_permissions(manage_guild=True)
@app_commands.choices(mode=[app_commands.Choice(name="On in this channel", value="on"),
                            app_commands.Choice(name="Off in this channel", value="off"),
                            app_commands.Choice(name="Every channel (quietly skips non-slips)", value="all"),
                            app_commands.Choice(name="Stop every-channel mode", value="all_off"),
                            app_commands.Choice(name="Show where it's on", value="show")])
@sec_staff_only
async def receipts_cmd(interaction: discord.Interaction, mode: Optional[app_commands.Choice[str]] = None):
    channel_id = interaction.channel_id
    m = mode.value if mode else None
    if m in ("all", "all_off"):
        set_setting(interaction.guild_id, "receipts_all", "on" if m == "all" else None)
        msg = ("📸 Every-channel mode is **on**: any screenshot that's a bet slip gets logged, anywhere in the server. "
               "Pictures that aren't slips are ignored quietly." if m == "all" else "Every-channel mode is **off**.")
        if m == "all" and not ai_enabled():
            msg += " ⚠️ It needs the Claude key (`ANTHROPIC_API_KEY` on Railway) to tell slips from other pictures."
        await interaction.response.send_message(msg)
        return
    if m == "show":
        rows = db().execute("SELECT channel_id FROM receipt_channels WHERE guild_id = ?", (interaction.guild_id,)).fetchall()
        where = ", ".join(f"<#{r['channel_id']}>" for r in rows) or "no channels"
        allm = get_setting(interaction.guild_id, "receipts_all") == "on"
        await interaction.response.send_message(
            f"Slip logging is on in: {where}." + (" Every-channel mode is **on** too." if allm else "") +
            "\nAnywhere else: @mention me with the screenshot (or reply to one with `@me log`).", ephemeral=True)
        return
    turn_off = channel_id in bot.receipt_channels if m is None else m == "off"
    if turn_off:
        db().execute("DELETE FROM receipt_channels WHERE channel_id = ?", (channel_id,))
        bot.receipt_channels.discard(channel_id)
        msg = "Slip logging is **off** for this channel."
    else:
        db().execute("INSERT OR REPLACE INTO receipt_channels (guild_id, channel_id) VALUES (?, ?)",
                     (interaction.guild_id, channel_id))
        bot.receipt_channels.add(channel_id)
        how = ("I'll read each screenshot and log it automatically."
               if ai_enabled() else
               "I'll reply to each screenshot with a button to log it.")
        msg = f"Slip logging is **on** for this channel. {how}"
        missing = missing_perms(getattr(interaction, "channel", None), getattr(getattr(interaction, "guild", None), "me", None))
        if missing:
            msg += f"\n⚠️ I'm missing **{', '.join(missing)}** here, so I can't reply. Fix my role or channel permissions."
    db().commit()
    await interaction.response.send_message(msg)


